void encoder_Loudness_action(char key)
{
	screen_Loudness_t *scr = screen_Loudness_get(&ui_manager);
    
    if(key == KEY_ENCODER_CW)          //编码器顺时针旋转
    {
		if (SET_Data.Set_VolumeFlag)
		{
			if (Set_Loudness_where == 0)
			{
				lv_group_focus_next(scr->group);
				if (scr->arrow_3_Btn == lv_group_get_focused(scr->group))
					lv_obj_set_style_text_opa(scr->KJHYQ_off_on_Lb, LV_OPA_100, LV_PART_MAIN | LV_STATE_DEFAULT);
				else
					lv_obj_set_style_text_opa(scr->KJHYQ_off_on_Lb, LV_OPA_30, LV_PART_MAIN | LV_STATE_DEFAULT);
				
			}
			else if (Set_Loudness_where == 1)
			{
				Set_Flag = (Set_Flag + 1) % 4;
				Set_Select_icon();
			}
		}
		else
		{
			g_send.buzzer_req = BUZZER_KEY_INVALID;
		}
		
    }
    else if(key == KEY_ENCODER_CCW)     //编码器逆时针旋转
    {
		if (SET_Data.Set_VolumeFlag)
		{
			if (Set_Loudness_where == 0)
			{
				lv_group_focus_prev(scr->group);
				if (scr->arrow_3_Btn == lv_group_get_focused(scr->group))
					lv_obj_set_style_text_opa(scr->KJHYQ_off_on_Lb, LV_OPA_100, LV_PART_MAIN | LV_STATE_DEFAULT);
				else
					lv_obj_set_style_text_opa(scr->KJHYQ_off_on_Lb, LV_OPA_30, LV_PART_MAIN | LV_STATE_DEFAULT);
			}
			else if (Set_Loudness_where == 1)
			{
				Set_Flag = (Set_Flag + 3) % 4;
				Set_Select_icon();
			}
		}
		else
		{
			g_send.buzzer_req = BUZZER_KEY_INVALID;
		}
    }
    else if(key == KEY_ENCODER_PRESS)         //编码器按下
    {
        if (scr->switch_bg_Btn == lv_group_get_focused(scr->group))
		{
			SET_Data.Set_VolumeFlag = !SET_Data.Set_VolumeFlag;
			if (SET_Data.Set_VolumeFlag)
				MSt_SoundMute_ON;
			else
				MSt_SoundMute_OFF;

			lv_obj_send_event(scr->switch_bg_Btn, LV_EVENT_CLICKED, NULL);
		}
		else if (scr->arrow_1_Btn == lv_group_get_focused(scr->group))	//提示音
		{
			if (Set_Loudness_where == 0)
			{
				Set_Loudness_where = 1;
				Set_Flag = SET_Data.Set_VolumeHintTime;
				TiShiYin_Cont_create();
			}
			else if (Set_Loudness_where == 1)
			{
				Set_Loudness_where = 0;
				SET_Data.Set_VolumeHintTime = Set_Flag;
				lv_obj_delete(scr->filter_Cont);
				lv_group_focus_obj(scr->arrow_1_Btn);
			}
		}
		else if (scr->arrow_2_Btn == lv_group_get_focused(scr->group))	//按键音
		{
			Set_Loudness_where = 2;
			lv_obj_clean(lv_screen_active());
			screen_Loudness_or_Luminance_Set_Val_create(&ui_manager, 1);
			lv_scr_load_anim(screen_Loudness_Set_Val_get(&ui_manager)->obj, LV_SCR_LOAD_ANIM_NONE, 0, 0, ui_manager.auto_del);
		}
		else if (scr->arrow_3_Btn == lv_group_get_focused(scr->group))	//开机欢迎曲
		{
			SET_Data.Set_VolumeWelcome = !SET_Data.Set_VolumeWelcome;
			if (SET_Data.Set_VolumeWelcome)
			{
				lv_label_set_text(scr->KJHYQ_off_on_Lb, tr("开"));
				MSt_BootTone_ON;
			}
				
			else
			{
				lv_label_set_text(scr->KJHYQ_off_on_Lb, tr("关"));
				MSt_BootTone_OFF;
			}
		}
    }
}

extern int8_t return_Set_focus;
void return_Loudness_action()
{
	screen_Loudness_t *scr = screen_Loudness_get(&ui_manager);

	if (Set_Loudness_where == 0)
	{
		return_Set_focus = 8;		//返回焦点
		lv_obj_clean(lv_screen_active());
		screen_SET_create(&ui_manager);
		lv_scr_load_anim(screen_SET_get(&ui_manager)->obj, LV_SCR_LOAD_ANIM_NONE, 0, 0, ui_manager.auto_del);
	}
	else
	{
		if (Set_Loudness_where == 1)
		{
			lv_obj_delete(scr->filter_Cont);
			lv_group_focus_obj(scr->arrow_1_Btn);
		}
		else if (Set_Loudness_where == 2)
		{
			lv_obj_delete(scr->filter_Cont);
			lv_group_focus_obj(scr->arrow_1_Btn);
		}

		Set_Loudness_where = 0;
	}
}

